from lesson_authoring import entry as E
B=[['拉丁 verbum','词；话语']]
W=[
E('verbalise','英 /ˈvɜːbəlaɪz/；美 /ˈvɜrbəlaɪz/','用语言表达〔常见英式拼写〕','把心里模糊的一团东西变成有名字、能交流的意思。','verbalize 的 -ise 拼写；verbal 接拉丁 verbum，-ise/-ize 形成动词。',B+[['晚期拉丁 verbalis → 英语 verbal','与词语有关'],['verbalise／verbalize','用词语表达']],'verbalise a thought 是把想法说出来。它和 verbalize 没有意义区别；英式也可以用 -ize，因此选择拼写后保持一致，比把另一种一概判错更实用。','verbalise thoughts；verbalise emotions；learn to verbalise。','verbalise 指形成语言表达，不保证表达已经清楚、真实或完整；这些还要看句子内容。',('The workshop helped participants verbalise their concerns.','工作坊帮助参与者把担忧说出来。'),('I could picture the idea but could not yet verbalise it.','我能想象那个点子，却还说不出来。'),sources=['https://en.wiktionary.org/wiki/verbalise','https://www.etymonline.com/word/verbalize']),
E('verbalization','英 /ˌvɜːbəlaɪˈzeɪʃən/；美 /ˌvɜrbələˈzeɪʃən/','语言表达；把想法说出来的过程','从心里的想法走到说出口的话，这个转换过程本身也可以被讨论。','verbalize + -ation，形成过程或结果名词；英式也写 verbalisation。',B+[['verbal → verbalize → verbalization','语言相关 → 用语言表达 → 表达过程或结果']],'the verbalization of thoughts 是想法的语言表达；a clear verbalization of a concern 是把担忧明确说出的话。它比 everyday expression 更偏讨论过程、教育或心理研究的语境。','the verbalization of feelings；encourage verbalization；a verbalization of an idea。','verbalization 不等于 explanation 解释：说出感受未必是在说明原因，也不一定涉及长篇分析。',('The exercise encourages the verbalization of each step in the reasoning process.','这个练习鼓励把推理过程中的每一步说出来。'),('Her short answer was a clear verbalization of the group’s concern.','她简短的回答清楚表达了团队的担忧。'),sources=['https://www.etymonline.com/word/verbalization','https://www.merriam-webster.com/dictionary/verbalization']),
E('verbose','英 /vɜːˈbəʊs/；美 /vərˈboʊs/','冗长啰嗦的；输出信息详尽的〔计算机〕','一句本来能讲清的话，被包上层层多余词语；在工具输出里，也可指把细节都打印出来。','借自拉丁 verbosus“充满词语的”；verb- 词，-osus 带有充满的意思，英语形成 verbose。',B+[['拉丁 verbosus','充满词语；话多的'],['英语 verbose','冗长的；技术中也指详细输出的']],'a verbose report 多半在批评报告啰嗦；verbose output 在软件里则常是中性功能，显示更多执行细节。不要看到 verbose 就一律理解成内容质量差，先看场景。','a verbose explanation；verbose output；verbose mode。','detailed 是细节多，未必多余；verbose 在普通写作评价中常指词多于必要。',('The first draft was verbose, so we removed repeated explanations.','初稿很啰嗦，所以我们删掉了重复解释。'),('Turn on verbose mode to see more details about each step.','打开详细输出模式，就能看到每一步的更多信息。'),sources=['https://www.etymonline.com/word/verbose','https://en.wiktionary.org/wiki/verbose']),
E('verbosity','英 /vɜːˈbɒsəti/；美 /vərˈbɑsəti/','冗长；啰嗦程度；输出详尽程度','把“说了多少、有没有多余”变成一个可以评价或调节的量。','经法语 verbosité 或晚期拉丁 verbositas 借入，接 verbosus 话多的；英语 verbosity 早于现代 verbose。',B+[['拉丁 verbosus → 晚期拉丁 verbositas','话多的 → 冗长这一性质'],['法语 verbosité／拉丁借入 → 英语 verbosity','冗长；后来也指输出详尽程度']],'reduce verbosity 在写作里是减少啰嗦；set the verbosity level 在工具里是设置显示多少细节。它与 verbose 的现代形容词—名词对应很清楚，但历史不是先有英语 verbose 才造 verbosity。','unnecessary verbosity；reduce verbosity；a verbosity level。','length 是长度，verbosity 常关乎措辞是否过多；简短却难懂的文本也未必好，目标是清楚且适量。',('The editor reduced the verbosity without removing useful examples.','编辑减少了啰嗦的表述，同时保留了有用的例子。'),('A higher verbosity level produces more diagnostic messages.','更高的详细程度设置会输出更多诊断信息。'),sources=['https://www.etymonline.com/word/verbosity','https://en.wiktionary.org/wiki/verbosity']),
E('proverb','英 /ˈprɒvɜːb/；美 /ˈprɑvɜrb/','谚语；格言','把大家反复观察到的经验压进一句容易记住的话，再代代传下去。','拉丁 pro- 向前、提出 + verbum 话 → proverbium；经法语 proverbe 等进入英语。',B+[['拉丁 pro + verbum → proverbium','提出的话 → 流传的警句、谚语'],['古法语 proverbe → 英语 proverb','谚语']],'an old proverb 是老谚语；quote a proverb 是引用谚语。它常给出经验或劝告，但流传很广不等于适用于所有情况；有时不同谚语甚至强调相反的处事方向。','an old proverb；as the proverb says；quote a proverb。','idiom 是固定习语，意义未必能由字面推出；proverb 通常是一句传达经验或道理的话。两者有联系，但不等同。',('My grandfather often used a proverb to make his point.','祖父常用一句谚语来说明自己的意思。'),('The class discussed whether the proverb applied to this situation.','全班讨论了这句谚语是否适用于这种情况。'),sources=['https://www.etymonline.com/word/proverb','https://en.wiktionary.org/wiki/proverb']),
E('proverbial','英 /prəˈvɜːbiəl/；美 /prəˈvɜrbiəl/','谚语中的；众所周知的；典型到常被提起的','一句熟话里的形象，被借到眼前的场景；或者某种特点出名到人人都知道。','接晚期拉丁 proverbialis，来自 proverbium；现代能联系 proverb + -ial，但保留拉丁形容词借入史。',B+[['拉丁 proverbium → proverbialis','谚语 → 谚语相关的'],['英语 proverbial','谚语中的；广为人知、典型的']],'the proverbial needle in a haystack 借大家熟悉的“大海捞针”式形象；his proverbial patience 是他出了名的耐心，不要求真有一句古谚语专门写他。','the proverbial needle in a haystack；proverbial wisdom；proverbial patience。','proverbial 可指真正谚语里的内容，也可泛指出了名的特点。它不是“动词之前的”，pro- 在这里不能机械按位置拆。',('Finding the missing file felt like searching for the proverbial needle in a haystack.','找那份丢失的文件，感觉就像人们常说的大海捞针。'),('Even her proverbial patience began to wear thin.','连她那出了名的耐心也开始耗尽了。'),sources=['https://www.etymonline.com/word/proverbial','https://www.merriam-webster.com/dictionary/proverbial'])
]
